facts.routine public.delete_user_account(uuid):
CREATE OR REPLACE FUNCTION public.delete_user_account(user_id_to_delete uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Analytics / logs
  DELETE FROM public.page_views         WHERE user_id = user_id_to_delete;
  DELETE FROM public.search_logs        WHERE user_id = user_id_to_delete;
  DELETE FROM public.analytics_events   WHERE user_id = user_id_to_delete;
  DELETE FROM public.digest_logs        WHERE user_id = user_id_to_delete;

  -- The person's cached syntheses (their search text and generated content)
  DELETE FROM public.topic_syntheses    WHERE user_id = user_id_to_delete;

  -- Preferences / consent
  DELETE FROM public.user_preferences   WHERE user_id = user_id_to_delete;
  DELETE FROM public.user_consents      WHERE user_id = user_id_to_delete;

  -- Feedback
  DELETE FROM public.synthesis_feedback WHERE user_id = user_id_to_delete;

  -- Social / saved content
  DELETE FROM public.followed_tags      WHERE user_id = user_id_to_delete;
  DELETE FROM public.saved_articles     WHERE user_id = user_id_to_delete;

  -- Reports & roles
  DELETE FROM public.reports            WHERE user_id = user_id_to_delete;
  DELETE FROM public.user_roles         WHERE user_id = user_id_to_delete;

  -- Auth record
  DELETE FROM auth.users                WHERE id = user_id_to_delete;
END;
$function$

facts.routine public.purge_expired_logs() · de:
CREATE OR REPLACE FUNCTION public.purge_expired_logs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  cutoff timestamptz := now() - interval '12 months';
  result jsonb := '{}'::jsonb;
  n integer;
BEGIN
  DELETE FROM public.page_views        WHERE created_at < cutoff;  GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('page_views', n);
  DELETE FROM public.search_logs       WHERE created_at < cutoff;  GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('search_logs', n);
  DELETE FROM public.analytics_events  WHERE created_at < cutoff;  GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('analytics_events', n);
  DELETE FROM public.digest_logs       WHERE sent_at    < cutoff;  GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('digest_logs', n);
  DELETE FROM public.synthesis_feedback WHERE created_at < cutoff; GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('synthesis_feedback', n);
  DELETE FROM public.topic_syntheses   WHERE created_at < cutoff;  GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('topic_syntheses', n);
  DELETE FROM public.analytics_signals WHERE date < cutoff::date;  GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('analytics_signals', n);
  DELETE FROM public.analytics_daily_snapshot WHERE date < cutoff::date; GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('analytics_daily_snapshot', n);
  DELETE FROM public.analytics_insights WHERE generated_at < cutoff; GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('analytics_insights', n);
  DELETE FROM public.analytics_opportunities WHERE suggested_at < cutoff; GET DIAGNOSTICS n = ROW_COUNT; result := result || jsonb_build_object('analytics_opportunities', n);

  INSERT INTO public.analytics_maintenance_log (action, details) VALUES ('purge_expired_logs', result);
  RETURN result;
END;
$function$

facts.routine public.record_enrichment_failure:
CREATE OR REPLACE FUNCTION public.record_enrichment_failure(p_id text, p_error text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_attempts integer;
  v_quarantined boolean;
  v_hide boolean;
BEGIN
  -- Lock the row: no other writer can change quarantine between this read and the update
  SELECT coalesce(enrichment_attempts, 0) + 1, coalesce(quarantined, false)
    INTO v_attempts, v_quarantined
    FROM public.articles WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'missing';
  END IF;

  v_hide := v_attempts >= 3 AND NOT v_quarantined;

  UPDATE public.articles SET
    enrichment_attempts   = v_attempts,
    needs_enrichment      = v_attempts < 3,
    force_retry           = false,
    last_enrichment_at    = now(),
    last_enrichment_error = left(coalesce(p_error, 'unknown error'), 1000),
    quarantined           = CASE WHEN v_hide THEN true ELSE quarantined END,
    quarantine_reason     = CASE WHEN v_hide THEN 'enrichment_failed' ELSE quarantine_reason END
  WHERE id = p_id;

  RETURN CASE WHEN v_hide THEN 'hidden' WHEN v_attempts >= 3 THEN 'kept' ELSE 'queued' END;
END;
$function$

facts.routine public.record_enrichment_refusal:
CREATE OR REPLACE FUNCTION public.record_enrichment_refusal(p_id text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_queued boolean;
  v_quarantined boolean;
  v_reason text;
BEGIN
  -- Lock the row: the eligibility check and the write below see the same version
  SELECT needs_enrichment, coalesce(quarantined, false), quarantine_reason
    INTO v_queued, v_quarantined, v_reason
    FROM public.articles WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'missing';
  END IF;
  IF v_queued IS NOT TRUE THEN
    RETURN 'changed';   -- published or otherwise changed meanwhile: leave it exactly as it is
  END IF;

  IF (v_reason IS NULL AND NOT v_quarantined) OR v_reason IN ('enrichment_failed', 'ai_refused') THEN
    UPDATE public.articles SET
      needs_enrichment      = false,
      force_retry           = false,
      quarantined           = true,
      quarantine_reason     = 'ai_refused',
      enrichment_attempts   = coalesce(enrichment_attempts, 0) + 1,
      last_enrichment_at    = now(),
      last_enrichment_error = 'Claude refused (stop_reason: refusal); waiting for the Codex fallback (npm run enrich:refused)'
    WHERE id = p_id;
    RETURN 'refused';
  END IF;

  -- admin / no_abstract / unknown quarantine: a normal failed attempt (same transaction, row lock held)
  RETURN public.record_enrichment_failure(p_id, 'Claude refused (stop_reason: refusal)');
END;
$function$

facts.routine public.search_articles_batch(tex:
CREATE OR REPLACE FUNCTION public.search_articles_batch(search_query text, species_scope text DEFAULT 'all'::text, filter_labels text[] DEFAULT NULL::text[], labels_match_all boolean DEFAULT false, filter_evidence text[] DEFAULT NULL::text[], filter_journals text[] DEFAULT NULL::text[], sort_order text DEFAULT 'relevance'::text, cursor_date date DEFAULT NULL::date, cursor_id text DEFAULT NULL::text, batch_size integer DEFAULT 500)
 RETURNS TABLE(id text, title text, clinical_bottom_line text, labels text[], source_journal text, publication_date date, authors text, pubmed_id text, doi text, article_url text, strength_of_evidence text, sort_key date, score double precision)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_order  text;
  v_cursor text;
  v_sql    text;
  v_outer  text;
BEGIN
  -- ── Input validation (SQLSTATE 22023 = invalid_parameter_value → API 400) ──────────────────
  IF search_query IS NULL OR length(btrim(search_query)) = 0 OR length(search_query) > 200 THEN
    RAISE EXCEPTION 'search_query must be 1–200 characters' USING ERRCODE = '22023';
  END IF;
  IF species_scope IS NULL OR species_scope NOT IN ('all', 'small-animal', 'large-animal') THEN
    RAISE EXCEPTION 'invalid species_scope' USING ERRCODE = '22023';
  END IF;
  IF sort_order IS NULL OR sort_order NOT IN ('relevance', 'newest', 'oldest') THEN
    RAISE EXCEPTION 'invalid sort_order' USING ERRCODE = '22023';
  END IF;
  IF batch_size IS NULL OR batch_size < 1 OR batch_size > 500 THEN
    RAISE EXCEPTION 'batch_size must be 1–500' USING ERRCODE = '22023';
  END IF;
  IF (cursor_date IS NULL) <> (cursor_id IS NULL) THEN
    RAISE EXCEPTION 'cursor_date and cursor_id must be given together' USING ERRCODE = '22023';
  END IF;
  IF sort_order = 'relevance' AND cursor_date IS NOT NULL THEN
    RAISE EXCEPTION 'relevance has a single pool and no cursor' USING ERRCODE = '22023';
  END IF;
  IF cursor_id IS NOT NULL AND length(cursor_id) > 100 THEN
    RAISE EXCEPTION 'invalid cursor' USING ERRCODE = '22023';
  END IF;
  IF coalesce(cardinality(filter_labels), 0) > 25 OR coalesce(cardinality(filter_evidence), 0) > 25
     OR coalesce(cardinality(filter_journals), 0) > 25 THEN
    RAISE EXCEPTION 'too many filter values' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(coalesce(filter_labels, '{}') || coalesce(filter_evidence, '{}')
                                  || coalesce(filter_journals, '{}')) v WHERE v IS NULL OR length(v) > 200) THEN
    RAISE EXCEPTION 'invalid filter value' USING ERRCODE = '22023';
  END IF;

  -- ── Order and keyset (fixed SQL fragments, chosen from validated enums) ─────────────────────
  IF sort_order = 'oldest' THEN
    v_order  := 'ORDER BY coalesce(a.publication_date, DATE ''1900-01-01'') ASC, a.id ASC';
    v_cursor := 'AND (coalesce(a.publication_date, DATE ''1900-01-01''), a.id) > ($8, $9)';
    v_outer  := 'ORDER BY p.sort_key ASC, p.id ASC';
  ELSE -- newest, and the relevance pool (the first newest batch)
    v_order  := 'ORDER BY coalesce(a.publication_date, DATE ''1900-01-01'') DESC, a.id DESC';
    v_cursor := 'AND (coalesce(a.publication_date, DATE ''1900-01-01''), a.id) < ($8, $9)';
    v_outer  := CASE WHEN sort_order = 'relevance' THEN 'ORDER BY score DESC, p.id'
                     ELSE 'ORDER BY p.sort_key DESC, p.id DESC' END;
  END IF;

  v_sql := '
    WITH q AS (
      SELECT websearch_to_tsquery(''english'', $1) AS broad_q,
             phraseto_tsquery(''english'', $1)     AS phrase_q,
             ARRAY[''Equine'',''equine'',''Large Animal'',''large animal'',''Livestock'',''livestock'',
                   ''Poultry'',''poultry'',''Food Animal'',''food animal'']::text[] AS large_labels,
             ARRAY[''Small Animal'',''small animal'']::text[]                    AS small_labels
    ),
    page AS (
      SELECT a.id, a.title, a.clinical_bottom_line, a.labels, a.source_journal, a.publication_date,
             a.authors, a.pubmed_id, a.doi, a.article_url, a.strength_of_evidence,
             coalesce(a.publication_date, DATE ''1900-01-01'') AS sort_key,
             a.search_vector
      FROM public.articles a, q
      WHERE a.needs_enrichment = false
        AND a.summary IS NOT NULL
        AND a.clinical_bottom_line IS NOT NULL
        AND (a.quarantined IS NULL OR a.quarantined = false)
        AND a.search_vector @@ q.broad_q
        AND CASE $2
              WHEN ''small-animal'' THEN (a.labels IS NULL
                                        OR NOT (a.labels && q.large_labels)
                                        OR a.labels && q.small_labels)
              WHEN ''large-animal'' THEN coalesce(a.labels && q.large_labels, false)
              ELSE true
            END
        AND ($3 IS NULL OR cardinality($3) = 0
             OR CASE WHEN $4 THEN coalesce(a.labels @> $3, false)
                     ELSE coalesce(a.labels && $3, false) END)
        AND ($5 IS NULL OR cardinality($5) = 0 OR a.strength_of_evidence = ANY ($5))
        AND ($6 IS NULL OR cardinality($6) = 0 OR a.source_journal = ANY ($6))
        ' || CASE WHEN cursor_date IS NULL THEN '' ELSE v_cursor END || '
      ' || v_order || '
      LIMIT $10
    )
    SELECT p.id, p.title, p.clinical_bottom_line, p.labels, p.source_journal, p.publication_date,
           p.authors, p.pubmed_id, p.doi, p.article_url, p.strength_of_evidence, p.sort_key,
           ' || CASE WHEN sort_order = 'relevance' THEN '
           (0.60 * ts_rank_cd(p.search_vector, q.broad_q, 32) +
            0.25 * ts_rank_cd(p.search_vector, q.phrase_q, 32) +
            0.10 * CASE WHEN lower(p.title) LIKE ''%'' || lower($1) || ''%'' THEN 1.0 ELSE 0.0 END +
            0.05 * GREATEST(public.similarity(lower(p.title), lower($1)),
                            public.similarity(lower(coalesce(p.clinical_bottom_line, '''')), lower($1))))::double precision'
           ELSE '0::double precision' END || ' AS score
    FROM page p, q
    ' || v_outer;

  RETURN QUERY EXECUTE v_sql
    USING search_query, species_scope, filter_labels, labels_match_all, filter_evidence,
          filter_journals, sort_order, cursor_date, cursor_id, batch_size;
END;
$function$

